type Position = { line: number; column: number };

type Node =
  | { kind: "text"; value: string }
  | { kind: "value"; path: string; escaped: boolean; position: Position }
  | {
      kind: "block";
      blockKind: "if" | "each";
      path: string;
      body: Node[];
      alternative: Node[];
      position: Position;
    };

type BlockNode = Extract<Node, { kind: "block" }>;

type Frame = {
  node: BlockNode;
  parent: Node[];
  elseSeen: boolean;
};

type Context = {
  root: unknown;
  current: unknown;
  index: number | undefined;
  inEach: boolean;
};

const MISSING = Symbol("missing");

function positionAt(source: string, offset: number): Position {
  let line = 1;
  let column = 1;
  for (let i = 0; i < offset; i++) {
    if (source.charCodeAt(i) === 10) {
      line++;
      column = 1;
    } else {
      column++;
    }
  }
  return { line, column };
}

function syntaxError(message: string, position: Position): Error {
  return new Error(`${message} at line ${position.line}, column ${position.column}`);
}

function requirePath(path: string, tag: string, position: Position): string {
  if (!path) throw syntaxError(`${tag} requires a path`, position);
  return path;
}

function parse(template: string): Node[] {
  const root: Node[] = [];
  const stack: Frame[] = [];
  let output = root;
  let cursor = 0;

  while (cursor < template.length) {
    const start = template.indexOf("{{", cursor);
    if (start === -1) {
      output.push({ kind: "text", value: template.slice(cursor) });
      break;
    }
    if (start > cursor) output.push({ kind: "text", value: template.slice(cursor, start) });

    const triple = template.startsWith("{{{", start);
    const openingLength = triple ? 3 : 2;
    const closing = triple ? "}}}" : "}}";
    const end = template.indexOf(closing, start + openingLength);
    const position = positionAt(template, start);
    if (end === -1) throw syntaxError("Unclosed tag", position);

    const content = template.slice(start + openingLength, end).trim();
    cursor = end + closing.length;

    if (triple) {
      output.push({
        kind: "value",
        path: requirePath(content, "Interpolation", position),
        escaped: false,
        position,
      });
      continue;
    }

    if (content.startsWith("!")) continue;

    if (content.startsWith("#")) {
      const match = /^#(\S+)(?:\s+([\s\S]*))?$/.exec(content);
      const blockKind = match?.[1];
      if (blockKind !== "if" && blockKind !== "each") {
        throw syntaxError(`Unknown block '${blockKind ?? content.slice(1)}'`, position);
      }
      const node: BlockNode = {
        kind: "block",
        blockKind,
        path: requirePath(match?.[2]?.trim() ?? "", `#${blockKind}`, position),
        body: [],
        alternative: [],
        position,
      };
      output.push(node);
      stack.push({ node, parent: output, elseSeen: false });
      output = node.body;
      continue;
    }

    if (content === "else") {
      const frame = stack.at(-1);
      if (!frame) throw syntaxError("'else' outside a block", position);
      if (frame.elseSeen) throw syntaxError("Duplicate 'else'", position);
      frame.elseSeen = true;
      output = frame.node.alternative;
      continue;
    }

    if (content.startsWith("/")) {
      const closingKind = content.slice(1).trim();
      const frame = stack.at(-1);
      if (!frame) throw syntaxError(`Unexpected closing block '/${closingKind}'`, position);
      if (closingKind !== frame.node.blockKind) {
        throw syntaxError(
          `Mismatched closing block: expected '/${frame.node.blockKind}', got '/${closingKind}'`,
          position,
        );
      }
      stack.pop();
      output = frame.parent;
      continue;
    }

    output.push({
      kind: "value",
      path: requirePath(content, "Interpolation", position),
      escaped: true,
      position,
    });
  }

  const unclosed = stack.at(-1);
  if (unclosed) {
    throw syntaxError(`Unclosed block '#${unclosed.node.blockKind}'`, unclosed.node.position);
  }
  return root;
}

function property(value: unknown, segments: string[]): unknown | typeof MISSING {
  let cursor = value;
  for (const segment of segments) {
    if ((typeof cursor !== "object" || cursor === null) && typeof cursor !== "function") {
      return MISSING;
    }
    if (!(segment in cursor)) return MISSING;
    cursor = (cursor as Record<string, unknown>)[segment];
  }
  return cursor;
}

function resolve(path: string, context: Context): unknown | typeof MISSING {
  if (path === "this") return context.inEach ? context.current : context.root;
  if (path === "@index") return context.inEach ? context.index : MISSING;

  if (path.startsWith("this.")) {
    if (!context.inEach) return MISSING;
    return property(context.current, path.slice(5).split("."));
  }

  const segments = path.split(".");
  if (context.inEach) {
    const local = property(context.current, segments);
    if (local !== MISSING) return local;
  }
  return property(context.root, segments);
}

function isTruthy(value: unknown | typeof MISSING): boolean {
  if (value === MISSING || value === null || value === undefined || value === false) return false;
  if (value === "" || value === 0 || value === 0n) return false;
  if (Array.isArray(value) && value.length === 0) return false;
  return true;
}

function scalar(value: unknown | typeof MISSING, path: string, position: Position): string {
  if (value === MISSING || value === null || value === undefined) return "";
  if (typeof value === "object" || typeof value === "function") {
    throw syntaxError(`Value at '${path}' cannot be rendered as scalar text`, position);
  }
  return String(value);
}

function escapeHtml(value: string): string {
  return value.replace(/[&<>"']/g, (character) => {
    switch (character) {
      case "&": return "&amp;";
      case "<": return "&lt;";
      case ">": return "&gt;";
      case '"': return "&quot;";
      default: return "&#39;";
    }
  });
}

function renderNodes(nodes: Node[], context: Context): string {
  let result = "";
  for (const node of nodes) {
    if (node.kind === "text") {
      result += node.value;
    } else if (node.kind === "value") {
      const value = scalar(resolve(node.path, context), node.path, node.position);
      result += node.escaped ? escapeHtml(value) : value;
    } else if (node.blockKind === "if") {
      result += renderNodes(isTruthy(resolve(node.path, context)) ? node.body : node.alternative, context);
    } else {
      const value = resolve(node.path, context);
      if (Array.isArray(value) && value.length > 0) {
        for (let index = 0; index < value.length; index++) {
          result += renderNodes(node.body, {
            root: context.root,
            current: value[index],
            index,
            inEach: true,
          });
        }
      } else {
        result += renderNodes(node.alternative, context);
      }
    }
  }
  return result;
}

/** Render a Mini Template string with the supplied data. */
export function render(template: string, data: unknown): string {
  return renderNodes(parse(template), {
    root: data,
    current: data,
    index: undefined,
    inEach: false,
  });
}
