./test/engine.test.ts
import { describe, expect, test } from "bun:test";
import { render } from "../src/engine";

describe("render", () => {
  test("escapes interpolation and leaves triple interpolation raw", () => {
    const data = { value: `&<>"'` };
    expect(render("{{value}}|{{{ value }}}", data)).toBe("&amp;&lt;&gt;&quot;&#39;|&<>\"'");
  });

  test("renders missing and null values as empty strings", () => {
    expect(render("a{{missing}}b{{nil}}c", { nil: null })).toBe("abc");
  });

  test("supports nested conditions and specified truthiness", () => {
    const template = "{{#if items}}Y{{#if enabled}}+{{else}}-{{/if}}{{else}}N{{/if}}";
    expect(render(template, { items: [1], enabled: false })).toBe("Y-");
    expect(render(template, { items: [], enabled: true })).toBe("N");
    expect(render("{{#if n}}yes{{else}}no{{/if}}", { n: 0 })).toBe("no");
  });

  test("iterates with local values, indexes, root fallback, and nested loops", () => {
    const template = "{{#each groups}}[{{name}}/{{title}}:{{#each this.items}}{{@index}}={{this}};{{else}}empty{{/each}}]{{else}}none{{/each}}";
    expect(render(template, {
      title: "root",
      groups: [
        { name: "a", items: ["x", "y"] },
        { name: "b", items: [] },
      ],
    })).toBe("[a/root:0=x;1=y;][b/root:empty]");
    expect(render("{{#each rows}}x{{else}}none{{/each}}", { rows: "no" })).toBe("none");
  });

  test("preserves whitespace and removes comments", () => {
    expect(render(" a \n{{! ignore me }}\n b ", {})).toBe(" a \n\n b ");
  });

  test("rejects non-scalar interpolation", () => {
    expect(() => render("{{user}}", { user: { name: "Ada" } })).toThrow("cannot be rendered as scalar text");
  });

  test("reports structural errors with line and column", () => {
    expect(() => render("x\n {{#wat x}}", {})).toThrow("Unknown block 'wat' at line 2, column 2");
    expect(() => render("{{#if x}}{{else}}{{else}}{{/if}}", {})).toThrow("Duplicate 'else'");
    expect(() => render("{{#if x}}{{/each}}", {})).toThrow("Mismatched closing block");
    expect(() => render("{{else}}", {})).toThrow("outside a block");
    expect(() => render("{{#if x}}", {})).toThrow("Unclosed block '#if'");
  });
});
./README.md
# Mini Template

A dependency-free TypeScript template renderer for Bun.

```ts
import { render } from "./src/engine";

render("Hello, {{user.name}}!", { user: { name: "Ada" } });
```

Supported syntax:

- `{{path}}` inserts HTML-escaped scalar text; `{{{path}}}` inserts raw text.
- `{{#if path}}...{{else}}...{{/if}}` conditionally renders nested content.
- `{{#each path}}...{{else}}...{{/each}}` iterates arrays. Use `{{this}}`, `{{this.field}}`, and `{{@index}}` inside loops. Other paths try the current item, then the root data.
- `{{! comment }}` renders nothing.

Objects and functions cannot be interpolated directly. Missing values render as empty strings. Invalid block structure throws an error with its line and column.

Run the CLI:

```sh
bun run src/cli.ts template.txt data.json
```

The rendered output is the only stdout content. Errors are written to stderr with a non-zero exit status.

Run checks:

```sh
bun test
bunx tsc --noEmit
```
